#[cfg(test)]
mod tests {
    use super::*;

    fn pool_str(id: StrId) -> &'static str {
        std::str::from_utf8(id.bytes()).expect("a table StrId must decode to UTF-8")
    }

    /// Every `StrId` reachable from a table must decode inside `STR_POOL`.
    ///
    /// The 32-bit packing is `(offset << 13) | len`, so a single wrong shift in
    /// the generator silently truncates or overruns a slice while still being
    /// in-bounds; the only symptom would be a wrong answer on a device.
    #[test]
    fn every_table_string_decodes_inside_the_pool() {
        let mut ids: Vec<StrId> = Vec::new();
        ids.extend_from_slice(&ALL_CLASS_SETS);
        ids.extend(ALL_CLASS_ROUTERS.iter().map(|(s, _)| *s));
        ids.extend(ALL_METHODS.iter().flat_map(|m| [m.name, m.sig]));
        ids.extend(ALL_NAME_METHODS.iter().map(|m| m.name));
        ids.extend(
            ALL_CLASS_METHODS
                .iter()
                .flat_map(|m| [m.cls, m.name, m.sig]),
        );
        ids.extend(STATIC_CONST_CLASSES.iter().map(|c| c.owner));
        ids.extend(STATIC_CONST_FIELDS.iter().map(|f| f.field));
        ids.extend(ALL_STEPS.iter().map(|s| s.s1));
        ids.extend(ALL_FMT_SEGS.iter().map(|s| s.s));
        assert!(
            ids.len() > 4_000,
            "tables unexpectedly small: {}",
            ids.len()
        );
        for id in ids {
            let _ = pool_str(id);
        }
    }

    /// Keys are never the empty string: an empty key would let a malformed
    /// lookup match the first entry of every binary search.
    #[test]
    fn dispatch_keys_are_never_empty() {
        for id in ALL_CLASS_SETS {
            assert!(!pool_str(id).is_empty());
        }
        for (id, _) in ALL_CLASS_ROUTERS {
            assert!(!pool_str(id).is_empty());
        }
        for m in ALL_METHODS {
            assert!(!pool_str(m.name).is_empty());
            assert!(!pool_str(m.sig).is_empty());
        }
        for m in ALL_CLASS_METHODS {
            assert!(!pool_str(m.cls).is_empty());
            assert!(!pool_str(m.name).is_empty());
            assert!(!pool_str(m.sig).is_empty());
        }
        for c in STATIC_CONST_CLASSES {
            assert!(!pool_str(c.owner).is_empty());
        }
    }

    /// `in_class_set` is a binary search: the range must be sorted or members
    /// are silently reported as strangers.
    #[test]
    fn class_set_ranges_are_sorted_and_answer_membership() {
        let start = 332;
        let end = 355;
        let range = &ALL_CLASS_SETS[start..end];
        assert!(
            range.windows(2).all(|w| w[0].bytes() < w[1].bytes()),
            "class-set range {start}..{end} is not strictly sorted"
        );
        for id in range {
            assert!(in_class_set(start, end, pool_str(*id)), "member rejected");
        }
        assert!(!in_class_set(start, end, "com.example.NotAStub"));
        assert!(!in_class_set(start, end, ""));
        // A member of the range is not visible from a sibling range.
        assert!(!in_class_set(start, end, pool_str(ALL_CLASS_SETS[0])));
    }

    /// `lookup_class_id` turns a class name into the dense router id that the
    /// generated `match` arms switch on; a sorted-range regression here routes
    /// every method of a class to the wrong stub.
    #[test]
    fn class_router_ids_are_dense_and_reachable() {
        let start = 0;
        let end = 134;
        let range = &ALL_CLASS_ROUTERS[start..end];
        assert!(
            range.windows(2).all(|w| w[0].0.bytes() < w[1].0.bytes()),
            "router range {start}..{end} is not strictly sorted"
        );
        for (id, mapped) in range {
            assert_eq!(lookup_class_id(start, end, pool_str(*id)), Some(*mapped));
        }
        assert_eq!(lookup_class_id(start, end, "com.example.NotAStub"), None);
    }

    /// The `StrId` packing round-trips: rebuilding the id from the decoded
    /// offset/length must produce the identical string.
    #[test]
    fn str_id_packing_round_trips() {
        for id in ALL_CLASS_SETS.iter().take(64) {
            let bytes = id.bytes();
            let off = (id.0 >> 13) as usize;
            let len = (id.0 & 0x1fff) as usize;
            assert_eq!((off, len), (off, bytes.len()));
            assert_eq!(&STR_POOL[off..off + len], bytes);
            assert_eq!(StrId(id.0).bytes(), bytes);
        }
    }

    /// Declarative ranges must be non-empty and inside their tables, otherwise a
    /// generated call site would panic on slice indexing at stub invocation time.
    #[test]
    fn step_and_method_ranges_are_in_bounds() {
        assert!(!ALL_STEPS.is_empty());
        assert!(!ALL_METHODS.is_empty());
        assert!(!ALL_FMT_SEGS.is_empty());
        assert!(!STATIC_CONST_FIELDS.is_empty());
        // `run_steps`/`exec_op` index these pools through `op_aux`/`op_arg`.
        for s in ALL_STEPS {
            assert!(str_pool_len() > 0);
            let _ = pool_str(s.s1);
        }
        for seg in ALL_FMT_SEGS {
            let _ = pool_str(seg.s);
        }
    }

    fn str_pool_len() -> usize {
        STR_POOL.len()
    }
}
